import 'package:local_auth/local_auth.dart';
Future<bool> bioAuth()async{
  final a=LocalAuthentication();
  final ok=await a.canCheckBiometrics&&await a.isDeviceSupported();
  if(!ok)return false;
  return await a.authenticate(localizedReason:'{{reason}}',options:const AuthenticationOptions(biometricOnly:true));}
